/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: item, mount, row, options
 * Tests
 *   - a shared identity names its Album entry and each track entry, needs a decision and stays expanded; matches by name decide nothing
 *   - a bound identity reuses its record, marks it hidden, and offers only replacing a different ID, sent with the record's captured revision
 *   - entries naming different Artists keep their own and offer reuse or create, never a replace
 *   - a preselected create or reuse is folded and needs no answer; an unbound identity may replace the ID of a candidate only while no listed record holds its own
 *   - an Artist another identity of the same list is bound to or reuses is disabled, while one used only in another list stays choosable
 *   - saving sends the whole decision set, saved decisions and edits alike with six keys each, and is disabled with nothing changed or while disabled
 *   - unsaved choices survive a new read, and are dropped once their identity is gone from one
 *   - the label row decides the label like an identity, with no list to share
 *   - a read that fails or runs out of time says so and is read again with Find matches
 *   - a row answered by a preselected reuse or a saved decision is folded behind it, showing what answers it
 *   - a saved reuse whose record changed since shows undecided with a note, and saving another row sends a set without it
 * @end-catalog */

import { cleanup, fireEvent, render, screen, waitFor, within } from '@testing-library/react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { captureAccountOperation } from '../../api/accountEpoch';
import { adminWorkspace } from './adminWorkspace';
import type { CatalogReview } from './catalogReviewApi';
import { capturedCatalogReview, reviewJson, session, viewer } from './catalogReviewFixtures.testSupport';
import { guestCandidateId, guestHandle, leadHandle, leadMusicBrainzId, leadOtherMusicBrainzId, leadRecordId, reviewAfterLookup, reviewIdentityResponse } from './catalogReviewLookupFixtures.testSupport';
import type { ReviewIdentityResponse } from './catalogReviewLookupApi';
import { CatalogReviewIdentities } from './CatalogReviewIdentities';

/**
 * The identity rows of an existing-Album review on their own, the identity read answered per test: what each row covers, what it
 * offers in each state, what a save sends, and how unsaved choices meet a new read. All names and identifiers are synthetic.
 */
const item = () => reviewAfterLookup(capturedCatalogReview());
function mount(read: () => ReviewIdentityResponse | Response = reviewIdentityResponse, disabled = false) {
  const fetch = vi.fn(async (path: string) => { const value = read(); return path.endsWith('/candidates') ? value instanceof Response ? value : reviewJson(value) : reviewJson({ code: 'unexpected' }, 500); });
  vi.stubGlobal('fetch', fetch);
  const client = new QueryClient({ defaultOptions: { queries: { retry: false } } }); client.setQueryData(['browser-session'], session);
  const onSave = vi.fn();
  const element = (value: CatalogReview) => <QueryClientProvider client={client}><CatalogReviewIdentities item={value} disabled={disabled} onSave={onSave} /></QueryClientProvider>;
  const view = render(element(item()));
  return { fetch, onSave, rerender: (value: CatalogReview) => view.rerender(element(value)), section: () => screen.getByRole('region', { name: 'Artists and label' }) };
}
/** The card of the row whose heading starts with `name`. */
const row = async (name: string) => (await screen.findAllByRole('listitem')).find(item => (item.querySelector('strong, summary')?.textContent ?? '').startsWith(name))!;
const options = (select: HTMLElement) => [...select.querySelectorAll('option')].map(option => [option.textContent, option.disabled]);
beforeEach(() => {
  adminWorkspace.reset(); adminWorkspace.authorize(captureAccountOperation(viewer), true, true, undefined, { editing: true, visibility: true }); adminWorkspace.select('admin');
});
afterEach(() => { cleanup(); adminWorkspace.reset(); vi.unstubAllGlobals(); });

test('a shared identity names its Album entry and each track entry, needs a decision and stays expanded; matches by name decide nothing', async () => {
  const { section } = mount();
  expect(await within(section()).findByText(/^Each artist is decided once for the Album and every track that credits it/)).toBeInTheDocument();
  const guest = await row('Synthetic guest');
  expect(guest.querySelector('details')).toBeNull();
  expect(within(guest).getByText('Needs a decision')).toBeInTheDocument();
  expect(within(guest).getAllByRole('listitem').map(entry => entry.textContent)).toEqual(['Album · Synthetic guest · Featured', '2 · Synthetic second track · Synthetic guest · Primary']);
  expect(options(within(guest).getByRole('combobox', { name: 'Synthetic guest · Decision' }))).toEqual([['Review later', false], ['Create as distinct', false],
    [`Reuse existing · Synthetic guest · Name match · Public · ${guestCandidateId.slice(-6)}`, false]]);
  expect(within(guest).getByRole('combobox')).toHaveValue('');
  expect(screen.getByText('Records to choose, existing or new: 1')).toHaveAttribute('role', 'status');
});

test('a bound identity reuses its record, marks it hidden, and offers only replacing a different ID, sent with the record\'s captured revision', async () => {
  const { onSave } = mount();
  const lead = await row('Synthetic catalog Artist');
  const summary = lead.querySelector('summary')!;
  expect(summary.textContent).toBe(`Synthetic catalog Artist · MusicBrainz ID ${leadMusicBrainzId} · Reuses Synthetic catalog Artist · Hidden`);
  const select = within(lead).getByRole('combobox', { name: 'Synthetic catalog Artist · Decision' });
  expect(options(select)).toEqual([[`Keep its MusicBrainz ID ${leadOtherMusicBrainzId}`, false],
    [`Reuse Synthetic catalog Artist and replace its MusicBrainz ID ${leadOtherMusicBrainzId} with ${leadMusicBrainzId} · ${leadRecordId.slice(-6)}`, false]]);
  const save = screen.getByRole('button', { name: 'Save decisions' });
  expect(save).toBeDisabled();
  fireEvent.change(select, { target: { value: `replace:${leadRecordId}` } });
  expect(save).toBeEnabled(); fireEvent.click(save);
  expect(onSave).toHaveBeenCalledWith([{ scope: 'artist', identity: leadHandle, boundName: 'Synthetic catalog Artist', action: 'replace', candidateId: leadRecordId, candidateRevision: 'b'.repeat(64) }]);
  cleanup();
  // A bound record that keeps no other ID offers no choice; a recorded ID says so.
  mount(() => { const data = reviewIdentityResponse(); data.identities[1].bound[0].musicBrainzId = null;
    data.identities[1].musicBrainzIdWrite = { scope: 'artist', identity: leadHandle, musicBrainzId: leadMusicBrainzId, replaces: null }; return data; });
  const recorded = await row('Synthetic catalog Artist');
  expect(within(recorded).queryByRole('combobox')).not.toBeInTheDocument();
  expect(within(recorded).getByText(`Records MusicBrainz ID ${leadMusicBrainzId}`)).toBeInTheDocument();
});

test('entries naming different Artists keep their own and offer reuse or create, never a replace', async () => {
  mount(() => { const data = reviewIdentityResponse(); data.identities[1] = { ...data.identities[1], state: 'conflicting', needsAnswer: true,
    bound: [data.identities[1].bound[0], { ...data.identities[1].bound[0], id: 'f'.repeat(24), name: 'Synthetic other Artist', visibility: 'public' }] };
    data.candidates.items.push({ ...data.candidates.items[0], id: 'd'.repeat(24), label: 'Synthetic catalog Artist', musicBrainzId: leadOtherMusicBrainzId }); return data; });
  const lead = await row('Synthetic catalog Artist');
  expect(within(lead).getByText(/^These entries name different Artists/)).toBeInTheDocument();
  expect(within(lead).getAllByRole('listitem').map(item => item.textContent)).toContain(`Synthetic catalog Artist · Hidden · ${leadRecordId.slice(-6)}`);
  const choices = options(within(lead).getByRole('combobox')).map(([text]) => text);
  expect(choices).toEqual(['Review later', 'Create as distinct', `Reuse existing · Synthetic catalog Artist · Name match · Public · keeps its MusicBrainz ID ${leadOtherMusicBrainzId} · ${'d'.repeat(6)}`]);
  expect(choices.some(text => String(text).startsWith('Reuse Synthetic catalog Artist and replace'))).toBe(false);
});

test('a preselected create or reuse is folded and needs no answer; an unbound identity may replace the ID of a candidate only while no listed record holds its own', async () => {
  mount(() => { const data = reviewIdentityResponse();
    data.identities[0] = { ...data.identities[0], needsAnswer: false, preselection: { scope: 'artist', identity: guestHandle, boundName: 'Synthetic guest', action: 'create-distinct', candidateId: null, candidateRevision: null } };
    data.candidates.items = []; return data; });
  const guest = await row('Synthetic guest');
  expect(guest.querySelector('summary')!.textContent).toBe('Synthetic guest · Preselected as new');
  expect(options(within(guest).getByRole('combobox'))[0]).toEqual(['Keep the preselected choice', false]);
  expect(screen.queryByText(/^Records to choose/)).not.toBeInTheDocument();
  cleanup();
  const id = '00000000-0000-4000-8000-0000000000c9';
  const withId = (holder: boolean) => () => { const data = reviewIdentityResponse(); data.identities[0] = { ...data.identities[0], musicBrainzId: id };
    data.candidates.items[0] = { ...data.candidates.items[0], musicBrainzId: '00000000-0000-4000-8000-0000000000d1' };
    if (holder) data.candidates.items.push({ ...data.candidates.items[0], id: 'e'.repeat(24), match: 'musicBrainzId', musicBrainzId: id }); return data; };
  mount(withId(false));
  const replaceable = options(within(await row('Synthetic guest')).getByRole('combobox')).map(([text]) => String(text));
  expect(replaceable.at(-1)).toBe(`Reuse Synthetic guest and replace its MusicBrainz ID 00000000-0000-4000-8000-0000000000d1 with ${id} · ${guestCandidateId.slice(-6)}`);
  cleanup();
  mount(withId(true));
  const held = options(within(await row('Synthetic guest')).getByRole('combobox')).map(([text]) => String(text));
  expect(held.some(text => text.includes('and replace'))).toBe(false);
  expect(held).toContain(`Reuse existing · Synthetic guest · Same MusicBrainz ID · Public · ${'e'.repeat(6)}`);
});

test('an Artist another identity of the same list is bound to or reuses is disabled, while one used only in another list stays choosable', async () => {
  const read = (shared: boolean) => () => { const data = reviewIdentityResponse();
    data.candidates.items.push({ ...data.candidates.items[0], id: leadRecordId, label: 'Synthetic guest' });
    if (!shared) data.identities[1].entries = [{ ...data.identities[1].entries[0], path: 'tracks.10000000-0000-4000-8000-000000000001.artists', slotId: '10000000-0000-4000-8000-000000000001' }];
    return data; };
  mount(read(true));
  expect(options(within(await row('Synthetic guest')).getByRole('combobox')).find(([text]) => String(text).endsWith(leadRecordId.slice(-6)))![1]).toBe(true);
  cleanup();
  mount(read(false));
  expect(options(within(await row('Synthetic guest')).getByRole('combobox')).find(([text]) => String(text).endsWith(leadRecordId.slice(-6)))![1]).toBe(false);
});

test('saving sends the whole decision set, saved decisions and edits alike with six keys each, and is disabled with nothing changed or while disabled', async () => {
  const { onSave } = mount(() => { const data = reviewIdentityResponse();
    data.identities[1].decision = { scope: 'artist', identity: leadHandle, boundName: 'Synthetic catalog Artist', boundMusicBrainzId: leadMusicBrainzId, action: 'replace', candidateId: leadRecordId, candidateRevision: 'b'.repeat(64) };
    return data; });
  const guest = await row('Synthetic guest'), save = screen.getByRole('button', { name: 'Save decisions' });
  expect(save).toBeDisabled();
  fireEvent.change(within(guest).getByRole('combobox'), { target: { value: guestCandidateId } });
  fireEvent.click(save);
  expect(onSave.mock.calls[0][0]).toEqual([
    { scope: 'artist', identity: guestHandle, boundName: 'Synthetic guest', action: 'reuse', candidateId: guestCandidateId, candidateRevision: 'c'.repeat(64) },
    { scope: 'artist', identity: leadHandle, boundName: 'Synthetic catalog Artist', action: 'replace', candidateId: leadRecordId, candidateRevision: 'b'.repeat(64) }]);
  // Choosing the saved decision again leaves nothing to save.
  fireEvent.change(within(guest).getByRole('combobox'), { target: { value: '' } });
  expect(save).toBeDisabled();
  cleanup();
  mount(reviewIdentityResponse, true);
  for (const control of [...(await screen.findAllByRole('combobox')), screen.getByRole('button', { name: 'Save decisions' })]) expect(control).toBeDisabled();
});

test('unsaved choices survive a new read, and are dropped once their identity is gone from one', async () => {
  let data = reviewIdentityResponse();
  const { rerender, onSave, fetch } = mount(() => data);
  fireEvent.change(within(await row('Synthetic guest')).getByRole('combobox'), { target: { value: 'create-distinct' } });
  const save = screen.getByRole('button', { name: 'Save decisions' });
  expect(save).toBeEnabled();
  // A lookup application advances the value revision: the rows are read again and the choice is kept.
  rerender({ ...item(), valueRevision: item().valueRevision + 1 });
  await waitFor(() => expect(fetch).toHaveBeenCalledTimes(2));
  await waitFor(() => expect(screen.getByRole('button', { name: 'Save decisions' })).toBeEnabled());
  expect(within(await row('Synthetic guest')).getByRole('combobox')).toHaveValue('create-distinct');
  // The identity is gone from the next read: its choice is dropped.
  data = { ...reviewIdentityResponse(), identities: [reviewIdentityResponse().identities[1]] };
  rerender({ ...item(), valueRevision: item().valueRevision + 2 });
  await waitFor(() => expect(fetch).toHaveBeenCalledTimes(3));
  await waitFor(() => expect(screen.queryByRole('combobox', { name: 'Synthetic guest · Decision' })).not.toBeInTheDocument());
  data = reviewIdentityResponse();
  rerender({ ...item(), valueRevision: item().valueRevision + 3 });
  await waitFor(() => expect(fetch).toHaveBeenCalledTimes(4));
  expect(within(await row('Synthetic guest')).getByRole('combobox')).toHaveValue('');
  expect(screen.getByRole('button', { name: 'Save decisions' })).toBeDisabled();
  expect(onSave).not.toHaveBeenCalled();
});

test('the label row decides the label like an identity, with no list to share', async () => {
  const { onSave } = mount(() => ({ ...reviewIdentityResponse(), identities: [], label: { name: 'Synthetic Label', musicBrainzId: null, state: 'unbound', bound: null, decision: null, preselection: null,
    needsAnswer: true, musicBrainzIdWrite: null }, candidates: { items: [{ ...reviewIdentityResponse().candidates.items[0], kind: 'organization', label: 'Synthetic Label', id: 'a'.repeat(24) }], unavailable: [] } }));
  const label = await row('Label · Synthetic Label');
  fireEvent.change(within(label).getByRole('combobox', { name: 'Synthetic Label · Decision' }), { target: { value: 'a'.repeat(24) } });
  fireEvent.click(screen.getByRole('button', { name: 'Save decisions' }));
  expect(onSave).toHaveBeenCalledWith([{ scope: 'label', identity: null, boundName: 'Synthetic Label', action: 'reuse', candidateId: 'a'.repeat(24), candidateRevision: 'c'.repeat(64) }]);
});

test('a read that fails or runs out of time says so and is read again with Find matches', async () => {
  let fail = true;
  const { fetch, section } = mount(() => fail ? reviewJson({ code: 'ADMIN_IMPORT_CANDIDATES_TIMEOUT' }, 503) : reviewIdentityResponse());
  expect(await within(section()).findByRole('alert')).toHaveTextContent('The request could not be confirmed. Your saved draft is retained.');
  fail = false;
  fireEvent.click(within(section()).getByRole('button', { name: 'Find matches' }));
  expect(await row('Synthetic guest')).toBeTruthy();
  expect(fetch).toHaveBeenCalledTimes(2);
});

test('a row answered by a preselected reuse or a saved decision is folded behind it, showing what answers it', async () => {
  const holder = { ...reviewIdentityResponse().candidates.items[0], id: 'e'.repeat(24), match: 'musicBrainzId' as const, musicBrainzId: leadMusicBrainzId };
  mount(() => { const data = reviewIdentityResponse();
    data.identities[0] = { ...data.identities[0], needsAnswer: false, decision: { scope: 'artist', identity: guestHandle, boundName: 'Synthetic guest', boundMusicBrainzId: null, action: 'create-distinct',
      candidateId: null, candidateRevision: null } };
    data.identities[1] = { ...data.identities[1], state: 'unbound', bound: [], preselection: { scope: 'artist', identity: leadHandle, boundName: 'Synthetic catalog Artist', action: 'reuse',
      candidateId: holder.id, candidateRevision: holder.revision } };
    data.candidates.items.push({ ...holder, label: 'Synthetic catalog Artist' }); return data; });
  const guest = await row('Synthetic guest'), lead = await row('Synthetic catalog Artist');
  expect(guest.querySelector('summary')!.textContent).toBe('Synthetic guest · Create as distinct');
  expect(within(guest).getByRole('combobox')).toHaveValue('create-distinct');
  expect(lead.querySelector('summary')!.textContent).toBe(`Synthetic catalog Artist · MusicBrainz ID ${leadMusicBrainzId} · Reuses Synthetic catalog Artist (same MusicBrainz ID)`);
  expect(within(lead).getByRole('combobox')).toHaveValue('');
  expect(options(within(lead).getByRole('combobox'))[0]).toEqual(['Keep the preselected choice', false]);
  expect(screen.queryByText(/^Records to choose/)).not.toBeInTheDocument();
  expect(screen.getByRole('button', { name: 'Save decisions' })).toBeDisabled();
});

test('a saved reuse whose record changed since shows undecided with a note, and saving another row sends a set without it', async () => {
  const { onSave } = mount(() => { const data = reviewIdentityResponse();
    data.identities[0].decision = { scope: 'artist', identity: guestHandle, boundName: 'Synthetic guest', boundMusicBrainzId: null, action: 'reuse', candidateId: guestCandidateId,
      candidateRevision: 'e'.repeat(64) };
    return data; });
  const guest = await row('Synthetic guest');
  expect(within(guest).getByText('The record chosen earlier has changed since. Choose again.')).toBeInTheDocument();
  const select = within(guest).getByRole('combobox', { name: 'Synthetic guest · Decision' });
  expect(select).toHaveValue('');
  // Another row's choice alone: the stale reuse is left out of the whole set the save replaces.
  fireEvent.change(within(await row('Synthetic catalog Artist')).getByRole('combobox'), { target: { value: `replace:${leadRecordId}` } });
  fireEvent.click(screen.getByRole('button', { name: 'Save decisions' }));
  const replace = { scope: 'artist', identity: leadHandle, boundName: 'Synthetic catalog Artist', action: 'replace', candidateId: leadRecordId, candidateRevision: 'b'.repeat(64) };
  expect(onSave).toHaveBeenLastCalledWith([replace]);
  // The changed record, listed at its new revision, can be chosen again, and that choice is sent at the new revision.
  fireEvent.change(select, { target: { value: guestCandidateId } });
  expect(within(guest).queryByText(/^The record chosen earlier/)).not.toBeInTheDocument();
  fireEvent.click(screen.getByRole('button', { name: 'Save decisions' }));
  expect(onSave).toHaveBeenLastCalledWith([{ scope: 'artist', identity: guestHandle, boundName: 'Synthetic guest', action: 'reuse', candidateId: guestCandidateId, candidateRevision: 'c'.repeat(64) }, replace]);
});
